tool_input.old_string:
export function subtotal(items) {
  return items.reduce((sum, item) => sum + item.price, 0);
}

tool_input.new_string:
export function subtotal(items) {
  return items.reduce((sum, item) => sum + item.price * item.qty, 0);
}

